<?php
namespace App\Domain\Industries;use App\Models\Industry;final class IndustryDependencyInspector{public function inspect(Industry $industry):array{$navigation=$industry->navigationItems()->where('is_active',true)->count();$homepage=$industry->homepageItems()->where('is_active',true)->count();$publicRelations=$industry->relatedSolutions()->publiclyVisible()->count()+$industry->relatedProducts()->publiclyVisible()->count()+$industry->relatedPages()->publiclyVisible()->count();$children=$industry->challenges()->count()+$industry->outcomes()->count()+$industry->needs()->count()+$industry->useCases()->count();return ['navigation'=>$navigation,'homepage'=>$homepage,'relations'=>$publicRelations,'children'=>$children,'blocked'=>$navigation+$homepage+$publicRelations>0];}}
